/** Funciones de TOTXCVETRA. 1-14 a nivel clave; 21-34 a nivel esquema. */
public enum FuncionL040 {
    ABRIR(0),
    SIS(1), SIS_BORI_BDES_PROD(2), SIS_BORI_BDES_PROD_INST(3), SIS_BORI_BDES_MON(4),
    SIS_BORI_BDES_PROD_MON(5), SIS_BORI_BDES_PROD_INST_MON(6), SIS_PROC(7),
    SIS_PROC_BORI_BDES_PROD(8), SIS_PROC_BORI_BDES_PROD_INST(9), SIS_PROC_BORI_BDES_MON(10),
    SIS_PROC_BORI_BDES_PROD_MON(11), SIS_PROC_BORI_BDES_PROD_INST_MON(12),
    SIS_PROC_BORI_BDES(13), SIS_BORI_BDES(14),
    // 21..34: mismas consultas a nivel esquema (codigo - 20)
    CERRAR(40), REABRIR(41);

    final int codigo;
    FuncionL040(int c) { codigo = c; }

    public static Optional<FuncionL040> de(int codigo) {
        int base = (codigo >= 21 && codigo <= 34) ? codigo - 20 : codigo;
        return Arrays.stream(values()).filter(f -> f.codigo == base).findFirst();
    }
    public static boolean esNivelEsquema(int codigo) { return codigo >= 21 && codigo <= 34; }
}

/** W77-RESULT-S151. El 9 se usa en el código pero no está en el encabezado. */
public enum ResultadoL040 {
    SIN_ERROR(0), FUNCION_INVALIDA(1), FECHA_INVALIDA(2), SISTEMA_SIN_TOTALES(3),
    PRODUCTO_SIN_TOTALES(4), INSTRUMENTO_SIN_TOTALES(5), BASE_CONTROL_NO_DISPONIBLE(6),
    BASE_DATOS_NO_DISPONIBLE(7), SISTEMA_NO_DADO_DE_ALTA(8), ERROR_DMSII(9), FIN_DE_DATOS(99);
    final int codigo;
    ResultadoL040(int c) { codigo = c; }
}

/** WKS-L40-CVES: entrada (llaves) y salida (hasta 100 renglones) en el mismo bloque. */
public record ConsultaTotalesRequest(
        int funcion,              // WKS-L40-FUN-L040   9(02) COMP
        LocalDate fecha,          // WKS-L40-FECHA      9(08) COMP, AAAAMMDD
        int sistema, int producto, int instrumento,
        int proceso,              // WKS-L40-PROCCON
        int bancoOrigen,          // WKS-L40-BORICON  9(03) dentro de BCOSCON 9(06)
        int bancoDestino,         // WKS-L40-BDESCON  9(03)
        int moneda,
        Continuacion desde) {     // CVETRACON + ESQCONCON: 0/0 = primera página

    public record Continuacion(int proceso, int producto, int instrumento,
                               int moneda, int cveTra, int esqCon) {}
}

public record TotalRenglon(int proceso, int moneda, int cveTra, int esqCon,
                           long numMov,            // 9(08) COMP
                           BigDecimal impMov,      // S9(13)V99 COMP, escala 2, con signo
                           int bancoOrigen, int bancoDestino) {}

public record ConsultaTotalesResponse(ResultadoL040 resultado,
                                      List<TotalRenglon> renglones,       // máx. 100
                                      ConsultaTotalesRequest.Continuacion siguiente) {}

@Service
@RequiredArgsConstructor
public class TotalesPorClaveTransaccionService {      // TOTXCVETRA, sin estado compartido

    private final MovDiaRepository movDia;             // BASEMOVDIA = S151BD10MOVDIA151
    private final ControlDiaService control;           // LIB-CONTROL / CONSISDIA

    @Transactional(readOnly = true)
    public ConsultaTotalesResponse consulta(ConsultaTotalesRequest rq) {
        int f = rq.funcion();
        if (f == 0 || f == 40 || f == 41) {
            return control.levanta(rq);                 // 00-0100-LEVANTA
        }
        if (!control.baseDisponible()) {               // WKS-INICIO / WKS-ABRE-SEM
            return vacia(control.inicializado() ? ResultadoL040.BASE_DATOS_NO_DISPONIBLE
                                                : ResultadoL040.FUNCION_INVALIDA);
        }
        return switch (FuncionL040.de(f).orElse(null)) {
            case SIS -> porSistema(rq);                                   // 01-0100-SIS
            case SIS_BORI_BDES_PROD -> porProducto(rq);                   // 02-0100-PRD
            // ... 3 a 14 con el mismo patrón ...
            case null, default -> vacia(ResultadoL040.FUNCION_INVALIDA);  // 15-20 y > 34
        };
    }
}

@Component
@RequiredArgsConstructor
public class ControlDiaService {

    private final LibControlClient libControl;     // CONSISDIA IN LIB-CONTROL, función 1
    private final MovDiaDataSourceRouter bases;    // la base MOVDIA cambia de título por sistema
    private final CsiProvider csi;                 // CSIID IN SOPORTECOMS

    /** 00-0100-LEVANTA: función 0 abre, 40 cierra, 41 reabre. */
    public ConsultaTotalesResponse levanta(ConsultaTotalesRequest rq) {
        return switch (rq.funcion()) {
            case 0 -> {
                if (bases.abierta(rq.sistema())) yield vacia(ResultadoL040.SIN_ERROR);
                var dia = libControl.consisdia(rq.sistema(), csi.numero());
                yield switch (dia.resultado()) {
                    case 0 -> dia.estadoBaseSemana() == 0
                            ? vacia(bases.abre(rq.sistema(), dia.nombreBaseSemana()))   // 0 o 7
                            : vacia(ResultadoL040.BASE_DATOS_NO_DISPONIBLE);            // 7
                    case 1 -> vacia(ResultadoL040.SISTEMA_NO_DADO_DE_ALTA);             // 8
                    default -> vacia(ResultadoL040.BASE_CONTROL_NO_DISPONIBLE);         // 6
                };
            }
            case 40 -> vacia(bases.cierra(rq.sistema()));
            case 41 -> vacia(bases.abre(rq.sistema(), null));
            default -> vacia(ResultadoL040.FUNCION_INVALIDA);
        };
    }
}

@Component
@RequiredArgsConstructor
public class MovDiaDataSourceRouter {

    private final MovDiaProperties props;      // reintento-espera: 20s, max-intentos: 5
    private final Map<Integer, DataSource> abiertas = new ConcurrentHashMap<>();

    /** 00-0130-ABRE-MOVDIA: OPEN UPDATE con reintento si la base está en uso exclusivo. */
    @Retryable(retryFor = BaseEnUsoExclusivoException.class,
               maxAttemptsExpression = "${movdia.max-intentos:5}",
               backoff = @Backoff(delayExpression = "${movdia.reintento-espera:20000}"))
    public ResultadoL040 abre(int sistema, String nombreBase) {
        if (nombreBase == null || nombreBase.isBlank()) return ResultadoL040.BASE_DATOS_NO_DISPONIBLE;
        abiertas.computeIfAbsent(sistema, s -> conecta(nombreBase));   // DMSTATUS 39 -> excepción reintentable
        return ResultadoL040.SIN_ERROR;
    }

    @Recover
    ResultadoL040 agotado(BaseEnUsoExclusivoException e, int sistema, String nombreBase) {
        log.error("ERROR EN BASE BD10 : ARCHIVO DE CONTROL EN USO EN FORMA EXCLUSIVA {}", e.detalle());
        return ResultadoL040.BASE_DATOS_NO_DISPONIBLE;   // el fuente reintenta sin fin
    }

    public ResultadoL040 cierra(int sistema) {
        var ds = abiertas.remove(sistema);
        return ds == null || Conexiones.cierra(ds) ? ResultadoL040.SIN_ERROR : ResultadoL040.ERROR_DMSII;
    }
}

/** 01-0100-SIS: funciones 1 (agrupa por clave de transacción) y 21 (renglón por esquema). */
private ConsultaTotalesResponse porSistema(ConsultaTotalesRequest rq) {
    boolean agrupaPorCve = rq.funcion() == 1;
    var cursor = rq.desde() == null
            ? movDia.primeroPorFecha(rq.fecha(), rq.moneda())     // 01-0150-FF-SIS
            : movDia.siguienteA(rq.fecha(), rq.desde());          // 01-0155-FF-CONT
    if (cursor.isEmpty()) return vacia(ResultadoL040.SISTEMA_SIN_TOTALES);   // 3

    var pagina = new PaginaTotales(100, agrupaPorCve);           // WKS-L40-IMPORTES OCCURS 100
    try (Stream<MovDia> filas = movDia.streamDesde(cursor.get())) {
        filas.takeWhile(r -> !pagina.llena())                    // UNTIL W77-IND = 100
             .forEach(pagina::acumula);                          // 01-0110-CONSIS
    }
    // Con 100 renglones, la función 1 sigue sumando en el último mientras no cambie la clave.
    return new ConsultaTotalesResponse(
            pagina.agotada() ? ResultadoL040.FIN_DE_DATOS : ResultadoL040.SIN_ERROR,
            pagina.renglones(), pagina.continuacion());
}

/** Estado de una página; vive solo durante la llamada (en COBOL era WORKING-STORAGE compartido). */
final class PaginaTotales {
    private final int max; private final boolean agrupaPorCve;
    private final List<TotalRenglon> renglones = new ArrayList<>();
    private ConsultaTotalesRequest.Continuacion continuacion;
    private boolean agotada = true;

    void acumula(MovDia r) {
        continuacion = r.llave();                          // WKS-L40-*CON := registro actual
        int i = renglones.size() - 1;
        if (agrupaPorCve && i >= 0 && renglones.get(i).cveTra() == r.cveTra()) {
            var t = renglones.get(i);
            renglones.set(i, t.suma(r.numMov(), r.impMov()));   // COMPUTE ... = B50 + acumulado
        } else if (renglones.size() < max) {
            renglones.add(TotalRenglon.de(r));                  // 01-0115-MUEVE-DATOS
        } else {
            agotada = false;                                    // W77-IND = 101: no se copia
        }
    }
    boolean llena() { return renglones.size() == max && !agrupaPorCve; }
    // TotalRenglon.suma: numMov 9(08) y impMov S9(13)V99 sin ON SIZE ERROR -> aquí Math.addExact
    // y BigDecimal.add con verificación de precisión 15; la suma de escala 2 es exacta.
}

public interface MovDiaRepository extends JpaRepository<MovDia, MovDiaId> {

    /** 01-0150-FF-SIS: primera fila de la fecha con moneda >= la pedida. */
    @Query("""
        select m from MovDia m
         where m.fecha = :fecha and m.moneda >= :moneda
         order by m.proceso, m.producto, m.instrumento, m.moneda, m.cveTra, m.esqCon""")
    Stream<MovDia> primeroPorFecha(LocalDate fecha, int moneda);

    /**
     * 01-0155-FF-CONT: la escalera de seis FIND FIRST (esqcon >, cvetra >, moneda >,
     * instrumento >, producto >, proceso >) es una búsqueda "mayor que" sobre la llave
     * compuesta del índice. En SQL es una comparación de tuplas (keyset pagination).
     */
    @Query(nativeQuery = true, value = """
        select * from movdia
         where fecha = :#{#fecha}
           and (proceso, producto, instrumento, moneda, cvetra, esqcon)
             > (:#{#d.proceso}, :#{#d.producto}, :#{#d.instrumento},
                :#{#d.moneda}, :#{#d.cveTra}, :#{#d.esqCon})
         order by proceso, producto, instrumento, moneda, cvetra, esqcon""")
    Stream<MovDia> siguienteA(LocalDate fecha, ConsultaTotalesRequest.Continuacion d);
}
// 01-0160-FN-CONXSIS: FIND NEXT ... AT fecha; NOTFOUND = 99 (fin de datos), otro error = 9.
